@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (_error is not null)
{
    <p class="error-message">Error: @_error</p>
}
else
{
    <BoardStats Total="@_allTasks.Count"
                TodoCount="@GetTasksByStatus("To Do").Count"
                InProgressCount="@GetTasksByStatus("In Progress").Count"
                DoneCount="@GetTasksByStatus("Done").Count"
                OverdueCount="@_allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchTerm="@_searchTerm" SearchTermChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Status="To Do"
                      Tasks="@GetFilteredTasksByStatus("To Do")"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRightClicked="@(task => MoveTask(task, "In Progress"))"
                      OnTaskCreated="HandleTaskCreated" />

        <KanbanColumn ColumnName="In Progress"
                      Status="In Progress"
                      Tasks="@GetFilteredTasksByStatus("In Progress")"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeftClicked="@(task => MoveTask(task, "To Do"))"
                      OnMoveRightClicked="@(task => MoveTask(task, "Done"))"
                      OnTaskCreated="HandleTaskCreated" />

        <KanbanColumn ColumnName="Done"
                      Status="Done"
                      Tasks="@GetFilteredTasksByStatus("Done")"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeftClicked="@(task => MoveTask(task, "In Progress"))"
                      OnTaskCreated="HandleTaskCreated" />
    </div>
}

@code {
    private List<TaskItem> _allTasks = new();
    private string _searchTerm = "";
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetTasksByStatus(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksByStatus(string status) =>
        _allTasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrEmpty(_searchTerm) ||
                        t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private void HandleSearchChanged(string term)
    {
        _searchTerm = term;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = _allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                _allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private async Task HandleTaskCreated((string Title, string Assignee, string Priority, DateTime DueDate, string Status) args)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(args.Title, args.Assignee, args.Priority, args.DueDate);
            _allTasks.Add(newTask with { Status = args.Status });
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }
}

